SELECT 



        (p.code LIKE CONCAT('%', #{keyword}, '%') OR p.name LIKE CONCAT('%', #{keyword}, '%'))

    AND p.status = #{status}
    AND p.type = #{type}
    AND p.manager_id = #{managerId}
    AND p.customer_id = #{customerId}

ORDER BY CASE p.status WHEN 'ACTIVE' THEN 0 WHEN 'PLANNING' THEN 1 WHEN 'APPROVING' THEN 1 WHEN 'SUSPENDED' THEN 2 ELSE 3 END, p.plan_end, p.id DESC
